#!/bin/sh
# Create deploy/.env with fresh random secrets. Refuses to overwrite an existing file: losing these secrets locks
# everyone out (the databases) or signs everyone out and breaks every token (Hydra). Back the file up.
set -eu
cd "$(dirname "$0")"
if [ -e .env ]; then
  echo "deploy/.env already exists; not overwriting it." >&2
  exit 1
fi
hex() { od -An -N32 -tx1 /dev/urandom | tr -d ' \n'; }
umask 077
cat > .env <<ENV
# LotusPond Accounts. Generated by make-secrets.sh on $(date -u +%Y-%m-%d). Keep a copy somewhere safe.
DOMAIN=accounts.lotuspond.ai
ACME_EMAIL=
SERVED_REGIONS=in

POSTGRES_PASSWORD=$(hex)
DIRECTORY_DB_PASSWORD=$(hex)
CELL_IN_DB_PASSWORD=$(hex)
HYDRA_DB_PASSWORD=$(hex)
HYDRA_SECRETS_SYSTEM=$(hex)
HYDRA_SECRETS_COOKIE=$(hex)
ACCOUNTS_DIRECTORY_SECRET=$(hex)
ACCOUNTS_COOKIE_SECRET=$(hex)

# Amazon SES (ap-south-1): an IAM user's keys allowed only ses:SendEmail from the verified lotuspond.ai identity.
SES_ACCESS_KEY_ID=
SES_SECRET_ACCESS_KEY=
ENV
echo "Wrote deploy/.env. Set ACME_EMAIL in it before starting on a server."
